const items = ($input.first().json.items) || [];
const parse = (s) => { if (!s) return null; const d = new Date(String(s).replace(' ', 'T')); return isNaN(d) ? null : d; };
const hourBerlin = (d) => parseInt(new Intl.DateTimeFormat('en-GB', { timeZone: 'Europe/Berlin', hour: '2-digit', hourCycle: 'h23' }).format(d), 10);
const now = new Date(); const DAY = 86400000;
if (hourBerlin(now) < 8 || hourBerlin(now) >= 20) return [];
const SITE = 'https://runrebels.com';
const sig = ['', 'Dein RunRebels-Team', 'ein Angebot von ASCENSUS'];
const out = [];
for (const r of items) {
  const b = parse(r.bestaetigt_am); if (!b || r.status !== 'bestaetigt') continue;
  const tage = (now - b) / DAY;
  const abm = 'Du willst keine Mails mehr? Hier trägst du dich aus: https://n8n.runrebels.com/webhook/crew-abmelden?t=' + r.abmelde_token;
  let aktion = null, betreff = '', zeilen = [];
  if (!r.mail2_gesendet && tage >= 4) {
    aktion = 'mail2'; betreff = 'Wer in der Crew läuft';
    zeilen = ['Hallo ' + r.vorname + ',', '', 'die Crew besteht aus Menschen, nicht aus Startnummern. Da läuft jemand im 80er-Trainingsanzug, jemand schiebt den Kinderwagen, jemand ist langsam und kommt stolz an. Alle laufen auf ihre Art, und alle gehören dazu.', '',
      'Wir zeigen das auf Instagram und TikTok: Gesichter, Geschichten und ein bisschen Rebellion gegen die Routine. Alle Kanäle findest du hier:', SITE + '/einblicke.html', '',
      'Allein laufen. Nie allein sein.', '', abm, ''].concat(sig);
  } else if (r.mail2_gesendet && !r.mail3_gesendet && tage >= 10) {
    aktion = 'mail3'; betreff = 'Jeder Lauf läuft für etwas';
    zeilen = ['Hallo ' + r.vorname + ',', '', 'bei RunRebels läuft jeder Lauf für etwas. Mit jeder Anmeldung unterstützt du einen guten Zweck. Wofür, und wie viel pro Anmeldung, geben wir vor dem Lauf bekannt. Nach dem Lauf rechnen wir offen ab.', '',
      'Dein erster Lauf kommt bald. Sobald Termin und Anmeldung feststehen, erfährst du es als Erste:r hier per Mail.', '',
      'Dein Start hilft jemandem.', '', abm, ''].concat(sig);
  }
  if (!aktion) continue;
  const patch = aktion === 'mail2' ? { mail2_gesendet: now.toISOString().replace('T', ' ') } : { mail3_gesendet: now.toISOString().replace('T', ' ') };
  out.push({ json: { id: r.id, an: r.email, aktion, betreff, text: zeilen.join('\n'), patch } });
}
return out;
